import json,os,re
from pathlib import Path
from datetime import datetime

def iter_msgs(p):
  with open(p,'r',encoding='utf-8',errors='replace') as f:
    for line in f:
      try:o=json.loads(line)
      except:continue
      # Cursor format: type=user/assistant with message.content
      t=o.get('type') or o.get('role') or ''
      msg=o.get('message') or o
      content=msg.get('content') if isinstance(msg,dict) else ''
      if isinstance(content,list):
        texts=[]
        for c in content:
          if isinstance(c,dict):
            if c.get('type') in ('text','input_text','output_text') or 'text' in c:
              texts.append(c.get('text') or '')
            elif c.get('type')=='tool_use':
              texts.append(f"[tool:{c.get('name','')}]")
          else:
            texts.append(str(c))
        content='\n'.join(texts)
      yield t, str(content or '')

def first_user_and_last_asst(p):
  first_u=None; last_a=None; users=[]; assts=[]
  for t,c in iter_msgs(p):
    if not c.strip(): continue
    tl=str(t).lower()
    if 'user' in tl or tl=='human':
      users.append(c)
      if first_u is None: first_u=c
    if 'assistant' in tl or 'model' in tl:
      assts.append(c); last_a=c
  return first_u, last_a, len(users), len(assts)

